import{_ as n,o as t,c as i,ak as g,bq as c}from"./chunks/framework.3a0Z_LB9.js";const e=JSON.parse('{"title":"Đăng ký hệ thống TT99/2025/TT-BTC","description":"","frontmatter":{},"headers":[],"relativePath":"TT99/dang-ky.md","filePath":"TT99/dang-ky.md"}'),a={name:"TT99/dang-ky.md"};function l(u,h,T,o,s,p){return t(),i("div",null,[...h[0]||(h[0]=[g('<h1 id="đang-ky-he-thong-tt99-2025-tt-btc" tabindex="-1">Đăng ký hệ thống TT99/2025/TT-BTC <a class="header-anchor" href="#đang-ky-he-thong-tt99-2025-tt-btc" aria-label="Permalink to “Đăng ký hệ thống TT99/2025/TT-BTC”">​</a></h1><p><img src="'+c+'" alt="tt99_new_dang_nhap.png"></p><p>Ứng dụng web tại địa chỉ <a href="https://a.bkit.vn" target="_blank" rel="noreferrer">https://a.bkit.vn</a> (a là viết tắt của từ accounting). Đây là model sản phẩm chiến lược quan trọng nhất của BKIT.</p><p>Liên hệ email <code>info@bkit.vn</code> hoặc/và Điện thoại <code>0903 237 207</code> trong giờ hành chính. Cung cấp thông tin Mã số thuế, Email quản trị viên Hệ thống phần mềm kế toán.</p><p>Giờ làm việc: Sáng 08:00 đến 12:00; Chiều: 13:30 đến 17:30; từ Thứ Hai đến Thứ Sáu, trừ ngày Lễ, Tết.</p><p>Bằng việc đăng ký hoặc/và đăng nhập, bạn đã chấp nhận &quot;Thỏa thuận sử dụng phần mềm kế toán BKIT&quot; tại <a href="https://learn.bkit.vn/TT133/thoa-thuan.html" target="_blank" rel="noreferrer">https://learn.bkit.vn/TT133/thoa-thuan.html</a> .</p><h2 id="can-cu-phap-ly-cua-phan-mem-ke-toan-bkit-theo-che-đo-ke-toan-ap-dung-thong-tu-99-2025-tt-btc" tabindex="-1">Căn cứ pháp lý của Phần mềm kế toán BKIT theo chế độ Kế toán áp dụng Thông tư 99/2025/TT-BTC <a class="header-anchor" href="#can-cu-phap-ly-cua-phan-mem-ke-toan-bkit-theo-che-đo-ke-toan-ap-dung-thong-tu-99-2025-tt-btc" aria-label="Permalink to “Căn cứ pháp lý của Phần mềm kế toán BKIT theo chế độ Kế toán áp dụng Thông tư 99/2025/TT-BTC”">​</a></h2><p>(cập nhật ngày 13/03/2026, danh sách rút gọn),</p><ul><li>Thông tư 20/2026/TT-BTC ban hành ngày 12/03/2026 quy định chi tiết một số điều của Luật Thuế thu nhập doanh nghiệp.</li><li>Nghị định 320/2025/NĐ-CP quy định chi tiết một số điều và biện pháp để tổ chức, hướng dẫn thi hành Luật Thuế thu nhập doanh nghiệp</li><li>Nghị định số 70/2025/NĐ-CP của Chính phủ: Sửa đổi, bổ sung một số điều của Nghị định số 123/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định về hóa đơn, chứng từ. Hiệu lực thi hành ngày 01/06/2025.</li><li>Thông tư số 32/2025/TT-BTC của Bộ Tài chính: Hướng dẫn thực hiện một số điều của Luật Quản lý thuế ngày 13 tháng 6 năm 2019, Nghị định số 123/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định về hóa đơn, chứng từ, Nghị định số 70/2025/NĐ-CP ngày 20 tháng 3 năm 2025 sửa đổi, bổ sung một số điều của Nghị định số 123/2020/NĐ-CP. Hiệu lực thi hành từ 01/06/2025.</li><li>Nghị quyết số 198/2025/QH15 của Quốc hội: Về một số cơ chế, chính sách đặc biệt phát triển kinh tế tư nhân. (Chấm dứt thu lệ phí môn bài)</li><li>Tiếp tục giảm thuế GTGT 8% từ 1/7/2025 đến hết 31/12/2026.</li><li>Luật thuế GTGT năm 2024 có hiệu lực từ 1/7/2025.</li><li>Nghị định 181 từ 1/7/2025, thay thế Nghị định 209.</li><li>Thông tư số 69/2025/TT-BTC từ 1/7/2025, thay thế Thông tư 219.</li><li>Nghị quyết 198/2025/QH15 Bỏ thuế khoán hộ kinh doanh từ 1/1/2026</li><li>Luật thuế TNDN 2025, có hiệu lực từ 1/10/2025</li><li>Nghị định số 320/2025/NĐCP từ 15/12/2025 thay thế Nghị định 218.</li><li>Nghị định 110 điều chỉnh mức giảm trừ gia cảnh của thuế TNCN từ 1/1/2026</li><li>Luật thuế TNCN 109/2025/QH15 từ 1/7/2026</li><li>Nghị định 310/2025/NĐ-CP (Sửa đổi Nghị định 125/2020/NĐ-CP) Mức phạt không lập hóa đơn, lập sai thời điểm.</li><li>Nghị định số 320/2025/NĐ-CP của Chính phủ: Quy định chi tiết một số điều và biện pháp để tổ chức, hướng dẫn thi hành Luật Thuế thu nhập doanh nghiệp, hiệu lực 15/12/2025.</li></ul><p>Nếu phân nhóm theo Căn cứ pháp lý theo chức năng:</p><p><strong>1. Chế độ Kế toán cơ sở</strong></p><ul><li><strong>Thông tư số 99/2025/TT-BTC:</strong> Hướng dẫn chế độ kế toán doanh nghiệp (Chế độ cốt lõi áp dụng cho phần mềm BKIT).</li><li><strong>Luật Kế toán số 88/2015/QH13:</strong> Cơ sở pháp lý cao nhất về công tác kế toán và tổ chức bộ máy kế toán tại Việt Nam.</li></ul><p><strong>2. Quản lý Hóa đơn, Chứng từ &amp; Xử phạt vi phạm</strong></p><ul><li><strong>Nghị định số 70/2025/NĐ-CP:</strong> Sửa đổi, bổ sung một số điều của Nghị định 123/2020/NĐ-CP quy định về hóa đơn, chứng từ (Hiệu lực từ 01/06/2025).</li><li><strong>Thông tư số 32/2025/TT-BTC:</strong> Hướng dẫn thực hiện Luật Quản lý thuế và các Nghị định 123/2020/NĐ-CP, Nghị định 70/2025/NĐ-CP về hóa đơn, chứng từ (Hiệu lực từ 01/06/2025).</li><li><strong>Nghị định số 310/2025/NĐ-CP:</strong> Sửa đổi Nghị định 125/2020/NĐ-CP, quy định chi tiết mức phạt đối với hành vi không lập hóa đơn hoặc lập sai thời điểm.</li></ul><p><strong>3. Thuế Giá trị gia tăng (GTGT)</strong></p><ul><li><strong>Luật Thuế GTGT năm 2024:</strong> Căn cứ luật định mới nhất về Thuế GTGT (Hiệu lực từ 01/07/2025).</li><li><strong>Nghị định số 181/2025/NĐ-CP:</strong> Thay thế Nghị định 209/2013/NĐ-CP về Thuế GTGT (Hiệu lực từ 01/07/2025).</li><li><strong>Thông tư số 69/2025/TT-BTC:</strong> Thay thế Thông tư 219/2013/TT-BTC, hướng dẫn thi hành Luật Thuế GTGT (Hiệu lực từ 01/07/2025).</li><li><strong>Chính sách hỗ trợ:</strong> Tiếp tục giảm thuế suất GTGT xuống 8% (Áp dụng từ 01/07/2025 đến hết 31/12/2026).</li></ul><p><strong>4. Thuế Thu nhập doanh nghiệp (TNDN)</strong></p><ul><li><strong>Luật Thuế TNDN năm 2025:</strong> (Hiệu lực từ 01/10/2025).</li><li><strong>Nghị định số 320/2025/NĐ-CP:</strong> Quy định chi tiết và hướng dẫn thi hành Luật Thuế TNDN, thay thế Nghị định 218/2013/NĐ-CP (Hiệu lực từ 15/12/2025).</li></ul><p><strong>5. Thuế Thu nhập cá nhân (TNCN)</strong></p><ul><li><strong>Luật Thuế TNCN số 109/2025/QH15:</strong> (Hiệu lực từ 01/07/2026).</li><li><strong>Nghị định số 110/2025/NĐ-CP:</strong> Điều chỉnh mức giảm trừ gia cảnh của thuế TNCN (Hiệu lực từ 01/01/2026).</li></ul><p><strong>6. Cơ chế đặc thù cho Kinh tế tư nhân &amp; Hộ kinh doanh</strong></p><ul><li><strong>Nghị quyết số 198/2025/QH15:</strong> Về một số cơ chế, chính sách đặc biệt phát triển kinh tế tư nhân. Trong đó quy định: Chấm dứt thu lệ phí môn bài và Bỏ thuế khoán đối với hộ kinh doanh (Áp dụng từ 01/01/2026).</li></ul><p>Nội dung được cập nhật lúc 19:33 Thứ Tư, 22 tháng 4, 2026 (GMT+7) Thời gian ở GMT+7</p>',23)])])}const N=n(a,[["render",l]]);export{e as __pageData,N as default};
